#!/usr/bin/env python3
"""Record root's completed CA mathematical review and verify its pinned sources.

The written mathematical verdict is a human review, not computed by this
script. The script checks source bytes and binds that verdict to the exact
reviewed paragraphs and final source ledger.
"""
from pathlib import Path
import argparse,hashlib,json,re,subprocess
ROOT=Path(__file__).resolve().parent
ap=argparse.ArgumentParser();ap.add_argument('--repo',type=Path,default=ROOT.parent/'lean-source');repo=ap.parse_args().repo
pin='7cbf7a0c32fca1badf05931879a37c3f8a2b03b4';d=json.loads((ROOT/'canonical_analytic/provenance.json').read_text());cache={};ranges=set()
def sha(b):return hashlib.sha256(b).hexdigest()
for c in d['claims']:
 for s in c['sources']:
  p=s['path']
  if p not in cache:cache[p]=subprocess.check_output(['git','-C',str(repo),'show',pin+':'+p])
  b=cache[p];assert sha(b)==s['sha256'],p
  z=b''.join(b.splitlines(keepends=True)[s['line_start']-1:s['line_end']]);assert sha(z)==s['range_sha256'],(p,s['line_start']);ranges.add((p,s['line_start'],s['line_end']))
notes={
 'CA1':'Expanded UxUy directly: the exponent difference is -pi*i*Im H(x,y); adding quadratic alpha gives precisely gamma(wx,y). The rationality uses the induced quadratic trace and exact area normalization, not arbitrary Gaussian algebraicity.',
 'CA2':'Checked the actual double finite representative formula and cancellation of chiF before algebraicity. Finite Fourier coefficients are averages of zeros and roots of unity. The quotient injection y -> cy gives the exact c^[E:Q]ab count including zero dimensions. No future JetAlg is used.',
 'CA3':'Checked the norm fibers of size q+1, sum -q, trace factorization of a conjugation-invariant character and surjectivity in characteristic2. There is no division by2 in the residue field.',
 'CA4':'Checked GoodNorm multiplicative root choice using equal residue degrees and conjugation-fixed prime behavior. Adjacent-lattice three cases give respectively 1,q_P,and the negative norm Gauss sum. The simple-submodule lattice step strictly decreases the finite index; no integral global basis is assumed.',
 'CA5':'Verified local Hom-module lengths repeat b times or a times. The even opposite rank cancels every conjugation-fixed-prime sign, identifying only the actual one-factor positive Iop with signed J. Pullback naturality follows termwise on representatives.',
 'CA6':'Checked anti-holomorphic/holomorphic kernel variables and the explicit diagonal identity. The finite-Iop side has frequency x+y, which contributes only at x=-y and the zero quotient class. In one eigen-coordinate the Gaussian factor is (h(1-zeta))^-1 exp[-pi*h*(1+zeta)/(2(1-zeta))*|s|²], matching the stated C and determinant inverse. Positive volume factors and Gaussian convergence are retained.',
 'CA7':'Checked half decomposition, swap and integral norm congruence modulo4m. The exponent defect is twice an integral pairing plus 2m times a quadratic cross-term. Multiplication by ell conjugates summands and is invertible modulo m. Both half sums agree and are real, so the full sum is nonnegative; nonzero follows from the isometry scalar.',
 'CA8':'Checked determinant identity det(gamma)*conj(det(1-gamma))=det(1-gamma) for even source rank, the opposite phase for the target inverse, and removal of eigenvalue1 by two rational norm-one scalar shifts. The final exponents are -b/2 and +a/2.',
 'CA9':'Checked both determinant ideal character transformations and all three EqP fields. Signed-intertwiner composition is applied to the actual thZero supplied by VI10, not a separately normalized theta family. The chiFac cancels exactly the computed phase.',
 'CA10':'Checked the local exponents for A_c and B_c, the finite-denominator CRT lift, Fourier zero-class reduction to1/n_c, lift independence via A_c/B_c integrality and the precise rational-unitary inverse in ThIndEq. ChiLaw remains explicit.',
 'CA11':'Checked actual no-conjugate-pair and degree-one/unramified local conditions, relative half-different unit conclusion, VI11 and covariance inputs, finite lattice and denominator classes and the finite algebraic generator field. All matrix entries lie in the field generated by finitely many embedded Q-bases of E. Only finite-order Taylor components are polynomials. The host-level VacIn/restriction argument avoids unused full Stages and NStage inputs.',
 'CA12':'Checked allSet retains its FinAlg restriction. The actual selected step satisfies it by CA11. Canonical exponents, exact modulus, rowSG/badP inclusions and total-degree identity remain on the same data; the fallback empty generator set is not used.',
 'CA13':'Checked fixed/full field-generator quantifiers, preserved context/base/frame/selector, raw PreX and frame-inclusion antecedents, exact amb0 and xi range through canonical replacement, same-field JetsIn and final universal ValLL0/FieldOK. A universal statement over later assemblies is explicitly distinguished from their existence.'
}
main=(ROOT/'canonical_analytic/main.tex').read_bytes();marks=list(re.finditer(rb'\\paragraph\{(CA\d+):',main));ph={}
for i,m in enumerate(marks):ph[m[1].decode()]=sha(main[m.start():marks[i+1].start()if i+1<len(marks)else len(main)])
assert set(ph)==set(notes)=={c['id']for c in d['claims']}
out=['INDEPENDENT MATHEMATICAL AND SOURCE REVIEW: CA1–CA13','Reviewer: /root','Version:0.17','Verdict: PASS under exact stated supplied-data hypotheses.','',
 'The entire draft was read and the central Gaussian/intertwiner calculations were checked independently. The diagonal-kernel frequency cancellation was expanded following this review. This record is independent of the author and does not assert Lean compilation, kernel replay or a completed RH/GRH proof.',
 f'Pinned source {pin}; {sum(len(c["sources"])for c in d["claims"])} links, {len(ranges)} unique ranges, {len(cache)} files; all source and range hashes agree.','']
for c in d['claims']:out += [c['id']+' — '+c['title'],'Paragraph SHA256: '+ph[c['id']],notes[c['id']],'']
out += ['Remaining scope: original raw PreX/frame assumptions, initial geometric and prime/window existence, arithmetic compatibility ties, full NStage/LocStage and independent quantitative branches. The completed canonical analytic supplier does not close those inputs.','Main SHA256: '+sha(main),'Report SHA256: '+sha((ROOT/'canonical_analytic/report.txt').read_bytes())]
(ROOT/'reviews_v0_17/root_reviews_ca.txt').write_text('\n'.join(out)+'\n')
print(json.dumps(dict(result='PASS',claims=len(ph),links=sum(len(c['sources'])for c in d['claims']),unique_ranges=len(ranges),files=len(cache))))
